input.newString:
import { Playfair_Display } from 'next/font/google';
import { Roboto } from 'next/font/google';

const playfair = Playfair_Display({ 
  subsets: ['latin'],
  weight: ['700'],
  variable: '--font-playfair'
});

const roboto = Roboto({ 
  subsets: ['latin'],
  weight: ['400'],
  variable: '--font-roboto'
});

export default function BlogHeader() {
  return (
    <header className={`${playfair.variable} ${roboto.variable}`} style={{
      fontFamily: 'var(--font-playfair), serif'
    }}>
      <h1 style={{
        fontFamily: 'var(--font-playfair), serif',
        fontSize: '3rem',
        fontWeight: '700',
        margin: '0 0 0.5rem 0'
      }}>My Personal Blog</h1>
      <p style={{
        fontFamily: 'var(--font-roboto), sans-serif',
        fontSize: '1.2rem',
        fontWeight: '400',
        margin: '0',
        color: '#666'
      }}>Thoughts, ideas, and musings</p>
    </header>
  );
}

